    @Test
    void returning_five_days_late_charges_500() throws Exception {
        String loanId = loanBookOn(LocalDate.of(2026, 1, 1));

        returnLoanOn(loanId, "2026-01-20")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_without_a_body_uses_today() throws Exception {
        String loanId = loanBookOn(LocalDate.now());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanBookOn(LocalDate.of(2026, 1, 1));

        returnLoanOn(loanId, "2025-12-31")
                .andExpect(status().isBadRequest());
    }

    private String loanBookOn(LocalDate loanedAt) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(registerBook(), registerMember(), loanedAt)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private ResultActions returnLoanOn(String loanId, String returnedAt) throws Exception {
        return mockMvc.perform(post("/loans/{loanId}/return", loanId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"returnedAt\":\"" + returnedAt + "\"}"));
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return loanRequest(bookId, memberId, null);
    }

    private String loanRequest(String bookId, String memberId, LocalDate loanedAt) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId, loanedAt));
    }

    record LoanBody(String bookId, String memberId, LocalDate loanedAt) {
    }
}

